import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第五卦 需 水天需 坎上乾下","description":"周易 - 第五卦 需 水天需 坎上乾下","frontmatter":{"title":"第五卦 需 水天需 坎上乾下","description":"周易 - 第五卦 需 水天需 坎上乾下"},"headers":[],"relativePath":"classics/zhouyi/006.md","filePath":"classics/zhouyi/006.md"}'),l={name:"classics/zhouyi/006.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="需" tabindex="-1">需 <a class="header-anchor" href="#需" aria-label="Permalink to “需”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>有孚，光亨，貞吉。利涉大川。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>需，須也；險在前也。剛健而不陷，其義不困窮矣。需有孚，光亨，貞吉。位乎天位，以正中也。利涉大川，往有功也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>雲上於天，需；君子以飲食宴樂。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>需 於郊。利用恆，無咎。象曰：需於郊，不犯難行也。利用恆，無咎；未失常也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>需於沙。小有言，終吉。象曰：需於沙，衍在中也。雖小有言，以終吉也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>需於泥，致寇至。象曰：需於泥，災在外也。自我致寇，敬慎不敗也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>需於血，出自穴。象曰：需於血，順以聽也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>需於酒食，貞吉。象曰：酒食貞吉，以中正也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>入於穴，有不速之客三人 來，敬之終吉。象曰：不速之客來，敬之終吉。雖不當位，未大失也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
